/**
 * Standard SMM Panel API v2. Authenticate with your API key.

Supported actions:
- `services` - Get list of services
- `add` - Create new order
- `status` - Get order status
- `multiple_status` - Get multiple orders status
- `balance` - Get account balance
- `refill` - Request refill
- `refill_status` - Get refill status
- `cancel` - Cancel order

 * @summary SMM Panel API v2 endpoint
 */
export const getApiV2Url = () => {
  return `/api/v2`;
};

export const apiV2 = async (
  apiV2Request: ApiV2Request,
  options?: RequestInit,
): Promise<ApiV2Response> => {
  const formUrlEncoded = new URLSearchParams();
  formUrlEncoded.append(`key`, apiV2Request.key);
  formUrlEncoded.append(`action`, apiV2Request.action);
  if (apiV2Request.service !== undefined) {
    formUrlEncoded.append(`service`, apiV2Request.service.toString());
  }
  if (apiV2Request.link !== undefined) {
    formUrlEncoded.append(`link`, apiV2Request.link);
  }
  if (apiV2Request.quantity !== undefined) {
    formUrlEncoded.append(`quantity`, apiV2Request.quantity.toString());
  }
  if (apiV2Request.order !== undefined) {
    formUrlEncoded.append(`order`, apiV2Request.order.toString());
  }
  if (apiV2Request.orders !== undefined) {
    formUrlEncoded.append(`orders`, apiV2Request.orders);
  }
  if (apiV2Request.runs !== undefined) {
    formUrlEncoded.append(`runs`, apiV2Request.runs.toString());
  }
  if (apiV2Request.interval !== undefined) {
    formUrlEncoded.append(`interval`, apiV2Request.interval.toString());
  }
  if (apiV2Request.comments !== undefined) {
    formUrlEncoded.append(`comments`, apiV2Request.comments);
  }
  if (apiV2Request.username !== undefined) {
    formUrlEncoded.append(`username`, apiV2Request.username);
  }

  return customFetch<ApiV2Response>(getApiV2Url(), {
    ...options,
    method: "POST",
    headers: {
      "Content-Type": "application/x-www-form-urlencoded",
      ...options?.headers,
    },
    body: formUrlEncoded,
  });
};

export const getApiV2MutationOptions = <
  TError = ErrorType<unknown>,
  TContext = unknown,
>(options?: {
  mutation?: UseMutationOptions<
    Awaited<ReturnType<typeof apiV2>>,
    TError,
    { data: BodyType<ApiV2Request> },
    TContext
  >;
  request?: SecondParameter<typeof customFetch>;
}): UseMutationOptions<
  Awaited<ReturnType<typeof apiV2>>,
  TError,
  { data: BodyType<ApiV2Request> },
  TContext
> => {
  const mutationKey = ["apiV2"];
  const { mutation: mutationOptions, request: requestOptions } = options
    ? options.mutation &&
      "mutationKey" in options.mutation &&
      options.mutation.mutationKey
      ? options
      : { ...options, mutation: { ...options.mutation, mutationKey } }
    : { mutation: { mutationKey }, request: undefined };

  const mutationFn: MutationFunction<
    Awaited<ReturnType<typeof apiV2>>,
    { data: BodyType<ApiV2Request> }
  > = (props) => {
    const { data } = props ?? {};

    return apiV2(data, requestOptions);
  };

  return { mutationFn, ...mutationOptions };
};

export type ApiV2MutationResult = NonNullable<
  Awaited<ReturnType<typeof apiV2>>
>;
export type ApiV2MutationBody = BodyType<ApiV2Request>;
export type ApiV2MutationError = ErrorType<unknown>;

